define(['jquery','Magento_Checkout/js/model/quote'],function($,quote){'use strict';var CheckoutAnalytics={config:{enabled:true,debug:false,sessionKey:'mab_checkout_session',events:[]},session:{sessionId:null,startTime:null,currentStep:null,events:[],errors:[]},init:function(){var self=this;if(!self.config.enabled){return;}
self.initSession();self.trackPageView();self.setupEventListeners();self.track('checkout_started',{cart_items:quote.getItems().length,cart_total:quote.getTotals()().grand_total});console.log('Checkout analytics initialized');},initSession:function(){var self=this;var stored=sessionStorage.getItem(self.config.sessionKey);if(stored){self.session=JSON.parse(stored);}else{self.session={sessionId:self.generateSessionId(),startTime:new Date().toISOString(),currentStep:'shipping',events:[],errors:[]};self.saveSession();}},generateSessionId:function(){return'checkout_'+Date.now()+'_'+Math.random().toString(36).substr(2,9);},saveSession:function(){try{sessionStorage.setItem(this.config.sessionKey,JSON.stringify(this.session));}catch(error){console.warn('Failed to save analytics session:',error);}},setupEventListeners:function(){var self=this;quote.shippingAddress.subscribe(function(address){if(address&&address.regionId){self.track('shipping_address_entered',{region_id:address.regionId,region:address.region,city:address.city});}});quote.shippingMethod.subscribe(function(method){if(method){self.track('shipping_method_selected',{carrier_code:method.carrier_code,method_code:method.method_code,amount:method.amount,method_title:method.method_title});}});quote.paymentMethod.subscribe(function(method){if(method){self.track('payment_method_selected',{method:method.method,title:method.title});}});self.trackFieldInteractions();self.trackErrors();self.trackTimeSpent();},trackFieldInteractions:function(){var self=this;var fieldTimings={};$('.checkout-index-index input, .checkout-index-index select').on('focus',function(){var fieldName=$(this).attr('name');if(fieldName){fieldTimings[fieldName]=Date.now();}});$('.checkout-index-index input, .checkout-index-index select').on('blur',function(){var fieldName=$(this).attr('name');if(fieldName&&fieldTimings[fieldName]){var duration=Date.now()-fieldTimings[fieldName];self.track('field_interaction',{field_name:fieldName,duration_ms:duration,has_value:!!$(this).val()});delete fieldTimings[fieldName];}});},trackErrors:function(){var self=this;$(document).on('ajaxError',function(event,jqXHR,settings,error){self.track('ajax_error',{url:settings.url,status:jqXHR.status,error:error});});$('.checkout-index-index').on('invalid-form.validate',function(){var errors=[];$('.field._error').each(function(){var fieldName=$(this).find('input, select').attr('name');var errorMsg=$(this).find('.mage-error').text();errors.push({field:fieldName,message:errorMsg});});self.track('validation_errors',{errors:errors,count:errors.length});});},trackTimeSpent:function(){var self=this;var stepStartTime=Date.now();var currentStep='shipping';$(window).on('beforeunload',function(){var duration=Date.now()-stepStartTime;self.track('step_time',{step:currentStep,duration_ms:duration,duration_sec:Math.round(duration / 1000)});var sessionDuration=Date.now()-new Date(self.session.startTime).getTime();self.track('checkout_session_end',{total_duration_ms:sessionDuration,total_duration_min:Math.round(sessionDuration / 60000),total_events:self.session.events.length});});},trackPageView:function(){this.track('page_view',{page:window.location.pathname,referrer:document.referrer,timestamp:new Date().toISOString()});},track:function(eventName,data){var self=this;if(!self.config.enabled){return;}
var event={event:eventName,data:data||{},timestamp:new Date().toISOString(),session_id:self.session.sessionId};self.session.events.push(event);self.saveSession();self.sendToAnalytics(eventName,data);if(self.config.debug){console.log('Analytics event:',eventName,data);}},sendToAnalytics:function(eventName,data){var self=this;if(window.gtag){try{window.gtag('event',eventName,data);}catch(error){console.warn('GA4 tracking error:',error);}}
if(window.fbq){try{window.fbq('trackCustom',eventName,data);}catch(error){console.warn('Facebook Pixel tracking error:',error);}}
if(window.dataLayer){try{window.dataLayer.push({event:eventName,eventData:data});}catch(error){console.warn('GTM tracking error:',error);}}
self.sendToCustomEndpoint(eventName,data);},sendToCustomEndpoint:function(eventName,data){var importantEvents=['checkout_started','shipping_method_selected','payment_method_selected','checkout_completed','checkout_abandoned'];if(importantEvents.indexOf(eventName)===-1){return;}
$.ajax({url:'/rest/V1/checkout-analytics/track',method:'POST',contentType:'application/json',data:JSON.stringify({event:eventName,data:data,session_id:this.session.sessionId,timestamp:new Date().toISOString()}),success:function(){console.log('Analytics sent to server:',eventName);},error:function(error){console.warn('Failed to send analytics to server:',error);}});},getSessionSummary:function(){var self=this;var now=Date.now();var startTime=new Date(self.session.startTime).getTime();var duration=now-startTime;return{session_id:self.session.sessionId,start_time:self.session.startTime,duration_ms:duration,duration_min:Math.round(duration / 60000),total_events:self.session.events.length,current_step:self.session.currentStep,errors:self.session.errors};},exportSession:function(){console.log('=== Checkout Analytics Session ===');console.log('Summary:',this.getSessionSummary());console.log('Events:',this.session.events);console.log('Full session:',this.session);return this.session;}};if($('body').hasClass('checkout-index-index')){$(document).ready(function(){CheckoutAnalytics.init();});}
window.CheckoutAnalytics=CheckoutAnalytics;return CheckoutAnalytics;});